    of assign-driven signals back to wire."""
    lhs = set(re.findall(r"\bassign\s+(\w+)", code))
    if not lhs:
        return code, False

    def fix_decl(m: re.Match) -> str:
        names = re.findall(r"[A-Za-z_][\w$]*", m.group(3))
        if any(n in lhs for n in names):
            return m.group(1) + "wire" + m.group(2) + m.group(3) + m.group(4)
        return m.group(0)

